{"Table":"bk_tb_feedback_auto_review","Create Table":"CREATE TABLE `bk_tb_feedback_auto_review` (\n  `id` varchar(36) NOT NULL,\n  `feedbackId` varchar(36) NOT NULL,\n  `owner` varchar(64) NOT NULL,\n  `mode` enum('shadow','assistive','automatic') NOT NULL,\n  `decision` enum('approve','correct','manual_review','reject') NOT NULL,\n  `score` double NOT NULL,\n  `fieldScores` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL CHECK (json_valid(`fieldScores`)),\n  `reasons` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL CHECK (json_valid(`reasons`)),\n  `suggestedCorrections` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`suggestedCorrections`)),\n  `reviewVersion` varchar(64) NOT NULL,\n  `evaluatedAt` datetime NOT NULL,\n  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),\n  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),\n  `applied` tinyint(1) NOT NULL DEFAULT 0,\n  `appliedAt` datetime DEFAULT NULL,\n  PRIMARY KEY (`id`),\n  UNIQUE KEY `IDX_feedback_auto_review_unique_shadow` (`feedbackId`,`mode`,`reviewVersion`)\n) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_uca1400_ai_ci","json":{"name":"bk_tb_feedback_auto_review.sql","path":"files/sql/rod/bk_tb_feedback_auto_review.sql","sha":"5aee99efae9d32b141567ebf9e932a29731b51be","size":62086,"url":"https://api.github.com/repos/rodcordeiro/shares/contents/files/sql/rod/bk_tb_feedback_auto_review.sql?ref=master","html_url":"https://github.com/rodcordeiro/shares/blob/master/files/sql/rod/bk_tb_feedback_auto_review.sql","git_url":"https://api.github.com/repos/rodcordeiro/shares/git/blobs/5aee99efae9d32b141567ebf9e932a29731b51be","download_url":"https://raw.githubusercontent.com/rodcordeiro/shares/master/files/sql/rod/bk_tb_feedback_auto_review.sql","type":"file","content":"eyJUYWJsZSI6ImJrX3RiX2ZlZWRiYWNrX2F1dG9fcmV2aWV3IiwiQ3JlYXRl\nIFRhYmxlIjoiQ1JFQVRFIFRBQkxFIGBia190Yl9mZWVkYmFja19hdXRvX3Jl\ndmlld2AgK